BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY;
SET LOCAL statement_timeout='15s'; SET LOCAL lock_timeout='5s';
WITH j AS (SELECT id,"tenantId","policySnapshot","calendarEventId" FROM "Job" WHERE id='9180bef4-561d-47a0-869f-925e6a3dfd96'::uuid AND "tenantId"='a1adcfd4-15be-404b-9ac3-5edb1fda20f0'::uuid),
t AS (SELECT id,status,settings->'organizationPaymentPolicyV1' AS "paymentPolicy" FROM "TenantOrganization" WHERE id='a1adcfd4-15be-404b-9ac3-5edb1fda20f0'::uuid),
u AS (SELECT id,"tenantId",email,"fullName",role,status FROM "User" WHERE "tenantId"='a1adcfd4-15be-404b-9ac3-5edb1fda20f0'::uuid AND email='debynyhan@signmons.com')
SELECT json_build_object(
 'jobCount',(SELECT count(*) FROM j),'job',(SELECT row_to_json(j) FROM j),
 'tenantCount',(SELECT count(*) FROM t),'tenant',(SELECT row_to_json(t) FROM t),
 'operatorCount',(SELECT count(*) FROM u),'operator',(SELECT row_to_json(u) FROM u),
 'calendarCount',(SELECT count(*) FROM "CalendarOperation" WHERE "jobId"='9180bef4-561d-47a0-869f-925e6a3dfd96'::uuid AND "tenantId"='a1adcfd4-15be-404b-9ac3-5edb1fda20f0'::uuid),
 'roleCount',(SELECT count(*) FROM pg_roles WHERE rolname='p07_payment_runtime'),
 'sessionCount',(SELECT count(*) FROM pg_stat_activity WHERE (usename='p07_payment_runtime' OR application_name LIKE 'signmons_p08_qualification_%' OR application_name IN ('p08-auth-cc2c1ce5-640f-41f4-a993-31063630207c','p08-runtime-cc2c1ce5-640f-41f4-a993-31063630207c','p08-probe-cc2c1ce5-640f-41f4-a993-31063630207c')) AND pid<>pg_backend_pid()));
ROLLBACK;

BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY;
SET LOCAL statement_timeout='15s'; SET LOCAL lock_timeout='5s';
WITH u AS (SELECT id,"tenantId",email,"fullName",role,status FROM "User"
 WHERE "tenantId"='a1adcfd4-15be-404b-9ac3-5edb1fda20f0'::uuid AND email='debynyhan@signmons.com')
SELECT json_build_object('operatorCount',(SELECT count(*) FROM u),
 'operator',(SELECT row_to_json(u) FROM u),
 'sessionsAbsent',NOT EXISTS(SELECT 1 FROM pg_stat_activity WHERE (usename='p07_payment_runtime' OR application_name LIKE 'signmons_p08_qualification_%' OR application_name IN ('p08-auth-cc2c1ce5-640f-41f4-a993-31063630207c','p08-runtime-cc2c1ce5-640f-41f4-a993-31063630207c','p08-probe-cc2c1ce5-640f-41f4-a993-31063630207c')) AND pid<>pg_backend_pid()));
ROLLBACK;
